mapper.select:
SELECT

FROM mes_equipment
WHERE is_active = 1

    AND equipment_code LIKE CONCAT('%', #{query.equipmentCode}, '%')


    AND equipment_name LIKE CONCAT('%', #{query.equipmentName}, '%')


    AND equipment_type = #{query.equipmentType}


    AND workshop = #{query.workshop}


    AND status = #{query.status}


    AND is_critical = #{query.isCritical}


    AND create_time >= #{query.createStartTime}


    AND create_time <= #{query.createEndTime}

ORDER BY


        ${query.sortField} ${query.sortOrder}


        create_time DESC

mapper.update:
UPDATE mes_equipment
SET
    status = #{status},
    update_time = #{updateTime},
    update_by = #{updateBy}
WHERE equipment_id = #{equipmentId}
